# ToolRegistry：工具注册表——AgentLoop 的安全门
# 对每次工具调用执行四层校验，防止 LLM 产生格式错误或恶意的工具参数
# ToolRegistry：核心类，封装了系统的关键行为和状态
class ToolRegistry:
    @staticmethod
    # _validate：内部辅助方法，供类内部其他方法调用
    def _validate(schema, arguments):
        # 第 1 层：必填参数检查——缺少 required 中的任何参数都报错
        missing = required.difference(arguments)
        if missing: raise AgentLoopProtocolError("missing required tool arguments: ...")
        # 第 2 层：额外参数检查——当 additionalProperties=false 时，不允许未声明的参数
        # 初始化集合 unknown，用于去重和快速查找
        unknown = set(arguments).difference(properties)
        if unknown: raise AgentLoopProtocolError("unknown tool arguments: ...")
        # 第 3 层：类型检查——确保每个参数类型与 schema 声明一致
        # 支持 string/integer/number/boolean/object/array 六种 JSON 类型
        for key, value in arguments.items():
            expected = expected_types.get(spec.get("type"))
            if expected and not isinstance(value, expected):
                raise AgentLoopProtocolError("tool argument %s must be %s" % ...)
        # 第 4 层：范围检查——数值类型可设置 minimum/maximum 约束
        if "minimum" in spec and value < spec["minimum"]: raise ...
        if "maximum" in spec and value > spec["maximum"]: raise ...
